"""MDP(Markov Decision Process) 정의 파일.

강화학습 문제는 (S, A, R, P, γ) 로 정의되는데, 이 파일이 그중
  S: 관측(상태)을 어떻게 구성할지  → OBSERVATION
  A: 행동을 무엇으로 할지          → SPEED_DELTAS
  R: 보상을 어떻게 줄지            → REWARD
  에피소드 길이/시간 해상도        → SIMULATION
를 결정한다. (전이확률 P는 SUMO 시뮬레이터 자체, γ는 train_config.py의 gamma)

이 파일만 수정하면 sumo_env.py를 건드리지 않고 MDP를 바꿀 수 있다.
"""

# ──────────────────────────────────────────────────────────────
# 1) 시뮬레이션 시간 설정
# ──────────────────────────────────────────────────────────────
SIMULATION = {
    "step_length": 0.5,   # SUMO 1스텝 = 0.5초. RL의 1 timestep과 동일.
                          # 작게 하면(0.1) 제어가 정밀해지지만 에피소드가 길어지고,
                          # 크게 하면(1.0) 학습이 빨라지지만 제어가 거칠어진다.
    "max_steps": 400,     # 에피소드 최대 스텝 수. 400 * 0.5초 = 200초.
                          # 이 시간 안에 완주 못하면 truncation(시간 초과) 처리.
    "warmup_steps": 20,   # ego를 넣기 전에 배경 교통을 미리 흘리는 스텝 수.
                          # 이게 없으면 매 에피소드가 텅 빈 도로에서 시작해버림.
}

# ──────────────────────────────────────────────────────────────
# 2) 관측 (Observation, 상태 S) — 19차원, 범위 [-1, 1]
#
# "내 차선 + 양옆 1차선씩" 총 3개 차선의 국소 교통 상황을 본다.
# 도로 구조(차선 수, 차선 감소 위치 등)에 하드코딩 없이 SUMO 네트워크를
# 실시간 조회하므로, 도로를 바꿔도 관측 코드는 그대로 동작한다.
#
# 레이아웃 (W = visibility, vmax = 제한속도):
#   [0]      내 절대속도 / vmax                                  (0 ~ 1)
#
#   차선별 블록 × 3 (순서: 왼쪽 차선, 현재 차선, 오른쪽 차선)
#   [1+4k]   선행차 상대거리 / W        (0~1,  없으면 1  = "앞이 뻥 뚫림")
#   [2+4k]   선행차 상대속도 / vmax     (-1~1, 없으면 1  = "위협 없음")
#   [3+4k]   후행차 상대거리 / W        (-1~0, 없으면 -1 = "뒤가 뻥 뚫림")
#   [4+4k]   후행차 상대속도 / vmax     (-1~1, 없으면 -1)
#     · 상대거리 부호: 선행 +, 후행 -  /  상대속도 = (상대차 속도 - 내 속도)
#     · 상대량이므로 내 절대속도[0]와 조합하면 절대값 복원 가능
#
#   차선 연결성(끊김 정도) × 3 (같은 순서)
#   [13],[14],[15]:
#        -1 : 그 차선이 아예 없음 (내가 맨 왼쪽이면 왼쪽 차선 = -1)
#         1 : W 이내에서 계속 이어짐
#      0~1  : 그 거리 비율(거리/W)만큼 가면 차선이 끝남
#             (다음 edge에 연결이 없는 차선 → 합류/차선감소 예고 신호)
#
#   차선별 전방 차량 밀도 × 3 (같은 순서)
#   [16],[17],[18]:
#      0~1  : (W 이내 전방 차량 수) / (최대 수용 대수)
#         0 : 텅 빈 차선  ↔  1 : 꽉 찬 차선
#         1 : 차선이 없는 경우도 1 = "꽉 찬 것" 취급 → 자연스럽게 회피 학습
#      · 곧 끊기는 차선은 남은 거리 기준으로 세므로 같은 대수여도 밀도가
#        높게 나온다 ("끊기는 차선에 차가 몰림" 신호)
# ──────────────────────────────────────────────────────────────
OBSERVATION = {
    "visibility": 50.0,          # 관측 가능 거리 W (m). 앞뒤 차량 감지와
                                 # 상대거리/연결성/밀도 정규화의 기준.
    "density_veh_length": 7.5,   # 밀도 계산 시 차량 1대의 점유 길이 (m)
                                 # = 차체(~5m) + 최소 안전간격(~2.5m).
                                 # 최대 수용 대수 = W / 이 값
}

# ──────────────────────────────────────────────────────────────
# 3) 행동 (Action, A) — 연속(continuous) 행동
#
# 행동은 a ∈ [-1, 1] 범위의 실수 "하나" (가속 페달/브레이크를 하나의 축으로).
#
#   a = +1.0  →  최대 가속  (+EGO["accel"] m/s², road_config.py에서 정의)
#   a =  0.0  →  현재 속도 유지
#   a = -1.0  →  최대 감속  (-EGO["decel"] m/s²)
#   중간값은 비례:  a = 0.5 → accel의 절반으로 가속
#
# 실제 가속도(m/s²)로의 변환은 sumo_env.py의 step()에서 수행:
#   accel_cmd = a * EGO["accel"]   (a ≥ 0 일 때)
#             = a * EGO["decel"]   (a <  0 일 때, decel은 양수이므로 결과는 음수)
#   한 스텝의 속도 변화량 = accel_cmd * step_length
#
# 가속/감속 한계를 바꾸고 싶으면 → road_config.py 의 EGO["accel"], EGO["decel"]
#
# ※ 연속 행동이므로 PPO는 Gaussian(정규분포) 정책을 사용한다 (ppo.py 참고).
# ──────────────────────────────────────────────────────────────
ACTION = {
    "dim": 1,   # 행동 차원 수. 현재는 가속도 1개.
                # (나중에 조향 등을 추가하면 2 이상으로 확장 가능)
}

# ──────────────────────────────────────────────────────────────
# 4) 보상 (Reward, R)
#
# 매 스텝 보상 = speed_weight * (현재속도 / vmax)          ← 빠를수록 +
#              - close_gap_penalty (간격 < threshold 일 때) ← 위험운전 벌점
# 종료 보상   = -collision_penalty (충돌)  또는  +arrival_bonus (완주)
#
# 설계 의도:
#   속도 보상만 있으면 "무조건 밟는" 정책이 나와 충돌한다.
#   충돌 벌점만 크면 "겁먹고 서 있는" 정책이 나온다.
#   이 둘 사이 균형을 잡는 것이 보상 설계(reward shaping)의 핵심이며,
#   아래 숫자들을 바꿔가며 정책이 어떻게 달라지는지 관찰해보길 권장.
# ──────────────────────────────────────────────────────────────
REWARD = {
    "speed_weight": 0.1,         # 속도 보상 가중치. 한 스텝 최대 +0.1
    "close_gap_threshold": 10.0, # 앞차와 이 거리(m) 미만으로 붙으면
    "close_gap_penalty": 0.2,    #   → 스텝당 이만큼 감점
    "collision_penalty": 5.0,    # 충돌 시 -5 를 받고 에피소드 즉시 종료
    "arrival_bonus": 2.0,        # 도로 끝까지 완주하면 +2 받고 종료
}
# 보상 스케일에 대한 메모 (수업에서 다뤄볼 만한 지점):
#   처음엔 speed_weight=1.0, collision=-10, arrival=+5 였는데,
#   400스텝 동안 스텝당 +1이 쌓이면 에피소드 리턴이 ~100까지 커진다.
#   그러면 (a) critic이 큰 값을 맞추느라 value_loss가 요동치고,
#          (b) "빨리 달리다 충돌(-10)" 이 "천천히 완주" 보다 이득이 되어
#              충돌 회피를 배울 유인이 약해진다.
#   그래서 속도 보상을 1/10로 줄여 리턴을 ~10 규모로 낮췄다.
#   → 보상의 절대값이 아니라 "항 사이의 상대 비율"이 정책을 결정한다는
#     점을 확인해보는 실험을 해보길 권장.
